/**
 * VoiceBill v3.0.2 — Production-Hardened Voice GST Invoicing & Payment Management SaaS
 * Includes Smart Parser v5 (Intent-Aware Prefix, Meta-Command & Partial Fallback Engine).
 * Secrets & payment credentials are loaded strictly from environment variables.
 */
const fs = require('fs');
const path = require('path');

const FILES = {
  "src/finance.js": "",
  "src/parser.js": "",
  "src/store.js": "",
  "src/server.js": "",
  "public/finance.js": "",
  "public/index.html": "",
  "public/portal.html": "",
  "public/styles.css": "",
  "public/app.js": "",
  "public/manifest.json": "",
  "public/sw.js": ""
};

for (const [relPath, b64] of Object.entries(FILES)) {
  const fullPath = path.join(__dirname, relPath);
  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, Buffer.from(b64, 'base64'));
}

console.log('[VoiceBill v3.0.2] Unpacked ' + Object.keys(FILES).length + ' verified modules.');
const { createApp } = require('./src/server.js');
const PORT = process.env.PORT || 3000;
createApp().listen(PORT, '0.0.0.0', () => {
  console.log('VoiceBill v3.0.2 SaaS listening on http://0.0.0.0:' + PORT);
});
